def write_int(memory, address, value, size):
    for i in range(size):
        memory[address + i] = value & 0xFF
        value >>= 8

def read_int(memory, address, size):
    value = 0
    for i in reversed(range(size)):
        value = value * 256 + memory[address + i]
    return value
